// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // fuzz blockNumber and caller key to find a block that is divisible by 10 but not 15
    function testFuzz_property(uint256 fuzzBlock, uint256 callerKey) public {
        callerKey = bound(callerKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep fuzzBlock in a reasonable range and non-zero
        uint256 blockNum = bound(fuzzBlock, 1, type(uint256).max - 1);
        // choose an EOA for the caller from the fuzzer-supplied key
        address caller = vm.addr(uint256(callerKey));

        // preconditions: we need the call to send exactly 10 ether
        vm.deal(caller, 20 ether);

        // set pastBlockTime to a time strictly less than the call time
        // set block timestamp to a known value
        uint256 callTime = 1000;
        vm.warp(callTime);

        // ensure pastBlockTime is strictly smaller so require(block.timestamp > pastBlockTime) holds
        // we can't call internal setter, so we simulate by first calling fallback once from setUp deploying value already set
        // but to ensure pastBlockTime < callTime, we can perform an initial call at an earlier timestamp
        // perform an initial benign call (10 ether) at time 500 and block 1 to set pastBlockTime
        vm.warp(500);
        vm.roll(1);
        vm.prank(caller);
        // initial call: send exactly 10 ether so it satisfies first require; block.timestamp (500) > initial pastBlockTime (0)
        // This may trigger a transfer back if block.number % 15 == 0 (block 1 not divisible) so safe
        (bool okInit, ) = address(c).call{value: 10 ether}("");
        require(okInit);

        // Now set the block number and time for the decisive call
        vm.warp(callTime);
        // choose the block number from fuzzed blockNum
        vm.roll(blockNum);

        // Make the decisive call from caller sending exactly 10 ether
        vm.prank(caller);
        // capture pre-call balance of caller and contract
        uint256 beforeCaller = caller.balance;
        uint256 beforeContract = address(c).balance;

        // perform low-level call to trigger fallback
        (bool ok, ) = address(c).call{value: 10 ether}("");
        // the reference and mutant might both return ok (fallback not reverting), so we can't rely on revert
        // Instead, observe whether the contract transferred its balance back by comparing balances after the call

        uint256 afterCaller = caller.balance;
        uint256 afterContract = address(c).balance;

        // General property to assert: For the reference contract, after a valid fallback call (exactly 10 ether,
        // timestamp greater than previous), the contract's balance is zero iff block.number % 15 == 0.
        // We assert the reference's behavior for the chosen (fuzzed) block; because we run tests against the reference
        // implementation in this file, the following must hold for all fuzz inputs. The mutant will violate it for
        // blocks divisible by 10 but not 15 (it would have sent the balance when block % 10 == 0).

        bool contractSentAll = (afterContract == 0);
        bool shouldHaveSentAll = (blockNum % 15 == 0);

        // Single assertion reading c's observable behavior (address(c).balance indirectly via afterContract)
        assertTrue(contractSentAll == shouldHaveSentAll);
    }
}
